oEICreconOuput::oEICreconOuput(TTree *tree) : fChain(0) 
{
// if parameter tree is not specified (or zero), connect the file
// used to generate this class and read the Tree.
   if (tree == 0) {
      TFile *f = (TFile*)gROOT->GetListOfFiles()->FindObject("../../../outputFiles/timeSplit/EicreconOut/oEicReconWOTimeSplit_18x275_Q2eq100_WBKG.root");
      if (!f || !f->IsOpen()) {
         f = new TFile("../../../outputFiles/timeSplit/EicreconOut/oEicReconWOTimeSplit_18x275_Q2eq100_WBKG.root");
      }
      f->GetObject("events",tree);

   }
   Init(tree);
}

oEICreconOuput::~oEICreconOuput()
{
   if (!fChain) return;
   delete fChain->GetCurrentFile();
}

Int_t oEICreconOuput::GetEntry(Long64_t entry)
{
// Read contents of entry.
   if (!fChain) return 0;
   return fChain->GetEntry(entry);
}
Long64_t oEICreconOuput::LoadTree(Long64_t entry)
{
// Set the environment to read one entry
   if (!fChain) return -5;
   Long64_t centry = fChain->LoadTree(entry);
   if (centry < 0) return centry;
   if (fChain->GetTreeNumber() != fCurrent) {
      fCurrent = fChain->GetTreeNumber();
      Notify();
   }
   return centry;
}

